"""Highest-weight vectors of the free (super)commutative algebra generated by the single-trace graviton
components u_n, v_n, w_n (n = 2..nmax) of fortuity.bmn.words.graviton_generators, and their evaluations.

For each generator type an independent set of components is chosen (the v_n components listed there are linearly
dependent); the raising operators E1, E2 are computed on components by acting on their word expansions and solving
in the span of the components of the same type.  A monomial is a sorted tuple of component ids (odd components at
most once, sign from sorting); E acts as an even derivation.  hw vectors are computed per multiset of types.
"""
import numpy as np
from collections import defaultdict, Counter
from fortuity.bmn.words import graviton_generators, expr_sector, content, add_term, canon_word
from fortuity.bmn.modp import P, RREFBasis, matmul_mod
from .hw import E_multi, nullspace_left


def canon_expr(expr):
    """Canonicalise every necklace (rotation with fermionic sign) and the multitrace ordering."""
    out = defaultdict(int)
    for m, c in expr.items():
        sign, words = 1, []
        for w in m:
            s, cw = canon_word(w)
            if not s:
                sign = 0
                break
            sign *= s
            words.append(cw)
        if sign:
            add_term(out, tuple(words), sign * c)
    return {m: c for m, c in out.items() if c}


def _expr_E(expr, i):
    out = defaultdict(int)
    for m, c in expr.items():
        for m2, c2 in E_multi(m, i).items():
            out[m2] += c * c2
    return {m: c for m, c in out.items() if c}


def _solve_mod(A, b, p=P):
    """x with x A = b (A: r x c, b: c), assuming solvable; returns x (length r)."""
    r = A.shape[0]
    Aug = np.concatenate([A % p, np.eye(r, dtype=np.int64)], axis=1)
    c = A.shape[1]
    # reduce rows of A, tracking combinations; then reduce b
    piv_rows, piv_cols = [], []
    row = 0
    for col in range(c):
        if row == r:
            break
        nz = np.nonzero(Aug[row:, col])[0]
        if nz.size == 0:
            continue
        pr = row + nz[0]
        Aug[[row, pr]] = Aug[[pr, row]]
        inv = pow(int(Aug[row, col]), p - 2, p)
        Aug[row] = (Aug[row] * inv) % p
        f = Aug[:, col].copy(); f[row] = 0
        nzr = np.nonzero(f)[0]
        if nzr.size:
            Aug[nzr] = (Aug[nzr] - np.outer(f[nzr], Aug[row])) % p
        piv_cols.append(col)
        row += 1
    rb = b % p
    x = np.zeros(r, dtype=np.int64)
    for i, col in enumerate(piv_cols):
        coef = rb[col]
        if coef:
            rb = (rb - coef * Aug[i, :c]) % p
            x = (x + coef * Aug[i, c:]) % p
    assert not rb.any(), "E-image not in the span of the type's components"
    return x


class GravitonAlgebra:
    def __init__(self, nmax, psipsi_coeff=1):
        gens = graviton_generators(nmax, psipsi_coeff)
        bytype = defaultdict(list)
        for name, e in gens:
            e = canon_expr(e)
            if not e:
                continue
            t = (name[0], name[1])
            bytype[t].append((name, e))
        self.comps = []          # list of (type, name, expr, sector, parity)
        self.types = sorted(bytype)
        type_ids = defaultdict(list)
        for t in self.types:
            # independent subset by rank over word coordinates
            items = bytype[t]
            cols = {}
            for _, e in items:
                for m in e:
                    cols.setdefault(m, len(cols))
            b = RREFBasis(len(cols))
            for name, e in items:
                v = np.zeros((1, len(cols)), dtype=np.int64)
                for m, c in e.items():
                    v[0, cols[m]] = c % P
                if b.add(v)[0]:
                    sec = expr_sector(e)
                    par = sum(content(next(iter(e)))[3:6]) % 2
                    type_ids[t].append(len(self.comps))
                    self.comps.append((t, name, e, sec, par))
        self.type_ids = dict(type_ids)
        self.sec = [np.array(c[3]) for c in self.comps]
        self.par = [c[4] for c in self.comps]
        # E action on components: Eact[i][cid] = list of (cid2, coeff)
        self.Eact = {1: {}, 2: {}}
        for t, ids in self.type_ids.items():
            for i in (1, 2):
                for cid in ids:
                    img = _expr_E(self.comps[cid][2], i)
                    if not img:
                        self.Eact[i][cid] = []
                        continue
                    tsec = expr_sector(img)
                    cand = [c2 for c2 in ids if tuple(self.comps[c2][3]) == tsec]
                    cols = {}
                    for c2 in cand:
                        for m in self.comps[c2][2]:
                            cols.setdefault(m, len(cols))
                    for m in img:
                        cols.setdefault(m, len(cols))
                    A = np.zeros((len(cand), len(cols)), dtype=np.int64)
                    for r, c2 in enumerate(cand):
                        for m, c in self.comps[c2][2].items():
                            A[r, cols[m]] = c
                    bvec = np.zeros(len(cols), dtype=np.int64)
                    for m, c in img.items():
                        bvec[cols[m]] = c
                    x = _solve_mod(A, bvec)
                    self.Eact[i][cid] = [(cand[r], int(x[r])) for r in np.nonzero(x)[0]]

    def monomials(self, sec):
        target = np.array(sec)
        out = []
        n = len(self.comps)

        def rec(start, rem, chosen):
            if not rem.any():
                out.append(tuple(chosen))
                return
            for i in range(start, n):
                if np.all(self.sec[i] <= rem):
                    chosen.append(i)
                    rec(i + 1 if self.par[i] else i, rem - self.sec[i], chosen)
                    chosen.pop()

        rec(0, target, [])
        return out

    def canon(self, mono):
        """Sort a tuple of component ids with the fermionic sign; (0, None) if an odd id repeats."""
        odd = [c for c in mono if self.par[c]]
        if len(set(odd)) < len(odd):
            return 0, None
        order = sorted(range(len(odd)), key=lambda i: odd[i])
        inv = sum(1 for a in range(len(order)) for b in range(a + 1, len(order)) if order[a] > order[b])
        return (-1 if inv % 2 else 1), tuple(sorted(mono))

    def E_mono(self, mono, i):
        out = defaultdict(int)
        for pos, cid in enumerate(mono):
            for c2, coef in self.Eact[i][cid]:
                s, m2 = self.canon(mono[:pos] + (c2,) + mono[pos + 1:])
                if s:
                    out[m2] += s * coef
        return {m: c % P for m, c in out.items() if c % P}

    def hw_blocks(self, sec):
        """List of (monomials, H) with rows of H hw vectors (combinations of the monomials)."""
        monos = self.monomials(sec)
        by_type = defaultdict(list)
        for m in monos:
            by_type[tuple(sorted(self.comps[c][0] for c in m))].append(m)
        blocks = []
        for tkey, ms in by_type.items():
            cols = {}
            ent = []
            for r, m in enumerate(ms):
                for i in (1, 2):
                    for m2, c in self.E_mono(m, i).items():
                        j = cols.setdefault((i, m2), len(cols))
                        ent.append((r, j, c))
            if cols:
                M = np.zeros((len(ms), len(cols)), dtype=np.int64)
                for r, j, c in ent:
                    M[r, j] = (M[r, j] + c) % P
                H = nullspace_left(M)
            else:
                H = np.eye(len(ms), dtype=np.int64)
            if H.shape[0]:
                blocks.append((ms, H))
        return blocks

    def rows(self, sec, frames):
        """hw graviton vectors in sector sec evaluated with DegFrames (rows, frames.ncols).  Components can mix
        fermion degrees (w_n), so every monomial is evaluated in each degree frame and projected on that degree."""
        return self.rows_from_blocks(self.hw_blocks(sec), frames)

    def rows_from_blocks(self, blocks, frames):
        if not blocks:
            return np.zeros((0, frames.ncols), dtype=np.int64)
        out = []
        cache = {}
        for ms, H in blocks:
            V = np.zeros((len(ms), frames.ncols), dtype=np.int64)
            for deg, fr in frames.frames.items():
                for r, m in enumerate(ms):
                    val = {0: np.ones((fr.P, 1), dtype=np.int64)}
                    for c in m:
                        a = self._val(c, fr, deg, cache)
                        new = {}
                        for d1, v1 in val.items():
                            for d2, v2 in a.items():
                                if d1 + d2 > deg:
                                    continue
                                pr, dd = fr.scal_mul(v1, d1, v2, d2)
                                new[dd] = (new[dd] + pr) % P if dd in new else pr
                        val = new
                        if not val:
                            break
                    if deg in val:
                        V[r, frames.off[deg]:frames.off[deg] + fr.ncols] = val[deg].reshape(-1)
            out.append(matmul_mod(H, V))
        return np.concatenate(out, axis=0)

    def _val(self, c, fr, deg, cache):
        """Component c evaluated in frame fr: dict {fermion degree <= deg: (P, C(k, d)) array}."""
        key = (c, deg)
        if key not in cache:
            e = self.comps[c][2]
            nv = fr.necklace_values([m[0] for m in e if sum(content(m)[3:6]) <= deg])
            acc = {}
            for m, coef in e.items():
                if m[0] not in nv:
                    continue
                v, d = nv[m[0]]
                term = (v * (coef % P)) % P
                acc[d] = (acc[d] + term) % P if d in acc else term
            cache[key] = acc
        return cache[key]
